<?php
if (PHP_SAPI !== 'cli') exit;
$base='http://localhost/sukamulya/';$db=new mysqli('localhost','root','','sukamulya');$db->set_charset('utf8mb4');
$tag='house_test_'.bin2hex(random_bytes(3));$pw='UjiRumah!'.bin2hex(random_bytes(5));$hash=password_hash($pw,PASSWORD_DEFAULT);$fail=0;
function hm_ok($v,$m){global $fail;echo($v?'PASS ':'FAIL ').$m.PHP_EOL;if(!$v)$fail++;}
class HmHttp{public $c,$body='',$code=0;function __construct(){$this->c=curl_init();curl_setopt_array($this->c,array(CURLOPT_RETURNTRANSFER=>1,CURLOPT_HEADER=>1,CURLOPT_COOKIEFILE=>'',CURLOPT_FOLLOWLOCATION=>0,CURLOPT_PROXY=>''));}function go($p,$data=NULL){global $base;if($data!==NULL){$token='';foreach(curl_getinfo($this->c,CURLINFO_COOKIELIST)as$c){$x=explode("\t",$c);if(($x[5]??'')==='csrf_sukamulya_cookie')$token=$x[6];}$data['csrf_sukamulya']=$token;curl_setopt_array($this->c,array(CURLOPT_POST=>1,CURLOPT_POSTFIELDS=>http_build_query($data)));}else curl_setopt($this->c,CURLOPT_HTTPGET,1);curl_setopt($this->c,CURLOPT_URL,$base.$p);$raw=curl_exec($this->c);$n=curl_getinfo($this->c,CURLINFO_HEADER_SIZE);$this->body=substr($raw,$n);$this->code=curl_getinfo($this->c,CURLINFO_HTTP_CODE);return $this;}}
$db->query("INSERT INTO admins(username,password_hash,role,is_active) VALUES('$tag','$hash','admin',1)");$aid=$db->insert_id;
$kk='88'.str_pad((string)random_int(1,99999999999999),14,'0',STR_PAD_LEFT);$db->query("INSERT INTO kk_families(nomor_kk,owner_citizen_id,fields_json,source) VALUES('$kk',NULL,'{\"alamat\":\"Alamat KK Lama\",\"rt\":\"009\",\"rw\":\"008\"}','admin_manual')");$fid=$db->insert_id;
$nik='77'.str_pad((string)random_int(1,99999999999999),14,'0',STR_PAD_LEFT);$mf=$db->real_escape_string(json_encode(array('nama_lengkap'=>'KELUARGA UJI RUMAH','nik'=>$nik,'hubungan_keluarga'=>'Kepala Keluarga','jenis_kelamin'=>'L')));$db->query("INSERT INTO kk_members(family_id,nik,fields_json,status) VALUES($fid,'$nik','$mf','aktif')");
$h=new HmHttp();$h->go('admin/login');$h->go('admin/login',array('username'=>$tag,'password'=>$pw));hm_ok(in_array($h->code,array(302,303,307),TRUE),'login admin uji');
$h->go('admin/rumah');hm_ok($h->code===200&&!preg_match('/Fatal error|A PHP Error|Database Error/',$h->body),'halaman Master Rumah tampil');
$code1='UJI-'.strtoupper(substr($tag,-6));$h->go('admin/rumah/baru');$h->go('admin/rumah/baru',array('house_code'=>$code1,'house_number'=>'12A','block_name'=>'Blok Uji','address_text'=>'Alamat Domisili 12A','building_type'=>'rumah','occupancy_status'=>'dihuni'));$hid1=(int)$db->query("SELECT id FROM rt_houses WHERE house_code='$code1'")->fetch_row()[0];hm_ok($hid1>0,'rumah 12A dibuat');
$h->go('admin/rumah/tautkan');$h->go('admin/rumah/tautkan',array('family_id'=>$fid,'house_id'=>$hid1,'occupancy_relation'=>'milik','start_date'=>'2026-11-01','verify'=>'1'));$r=$db->query("SELECT * FROM rt_family_residences WHERE family_id=$fid AND end_date IS NULL")->fetch_assoc();hm_ok($r&&(int)$r['house_id']===$hid1&&$r['verification_status']==='verified','KK terhubung dan terverifikasi di rumah 12A');
$code2=$code1.'B';$h->go('admin/rumah/baru');$h->go('admin/rumah/baru',array('house_code'=>$code2,'house_number'=>'13','block_name'=>'Blok Uji','address_text'=>'Alamat Domisili 13','building_type'=>'rumah','occupancy_status'=>'dihuni'));$hid2=(int)$db->query("SELECT id FROM rt_houses WHERE house_code='$code2'")->fetch_row()[0];$h->go('admin/rumah/tautkan');$h->go('admin/rumah/tautkan',array('family_id'=>$fid,'house_id'=>$hid2,'occupancy_relation'=>'kontrak','start_date'=>'2026-11-10','verify'=>'1'));$old=$db->query("SELECT end_date FROM rt_family_residences WHERE family_id=$fid AND house_id=$hid1 ORDER BY id DESC LIMIT 1")->fetch_row()[0];$active=(int)$db->query("SELECT COUNT(*) FROM rt_family_residences WHERE family_id=$fid AND end_date IS NULL")->fetch_row()[0];hm_ok($old==='2026-11-09'&&$active===1,'pindah rumah menutup histori lama dan menyisakan satu domisili aktif');
$h->go('admin/keluarga?detail='.$fid);hm_ok($h->code===200&&strpos($h->body,'Master KK, Rumah')!==FALSE&&strpos($h->body,'Alamat Domisili 13')!==FALSE,'halaman gabungan menampilkan rumah aktif dan panel detail');
$aud=$tag.'_aud';$db->query("INSERT INTO admins(username,password_hash,role,is_active) VALUES('$aud','$hash','auditor',1)");$auid=$db->insert_id;$a=new HmHttp();$a->go('admin/login');$a->go('admin/login',array('username'=>$aud,'password'=>$pw));$a->go('admin/rumah');hm_ok($a->code===200,'auditor dapat membaca master rumah');$a->go('admin/rumah/baru');hm_ok($a->code===403,'auditor ditolak saat membuka form perubahan rumah');
$db->query("DELETE FROM rt_family_residences WHERE family_id=$fid");$db->query("DELETE FROM rt_houses WHERE id IN($hid1,$hid2)");$db->query("DELETE FROM kk_members WHERE family_id=$fid");$db->query("DELETE FROM kk_families WHERE id=$fid");$db->query("DELETE FROM admins WHERE id=$aid");
$db->query("DELETE FROM admins WHERE id=$auid");
exit($fail?1:0);
